function sumOfThree(num) {
  if (num % 3 !== 0) {
    return [];
  }

  const middle = num / 3;
  return [middle - 1, middle, middle + 1];
}

brute:
function sumOfThree(num) {
  // x + (x + 1) + (x + 2) grows with x, so binary search the smallest start x whose total reaches num.
  let low = -1, high = num;
  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    if (mid + (mid + 1) + (mid + 2) >= num) high = mid;
    else low = mid + 1;
  }
  return low + (low + 1) + (low + 2) === num ? [low, low + 1, low + 2] : [];
}

