function generate(rand, size) {
  if (size === 'small') {
    const roll = rand();
    if (roll < 0.1) return [0];
    return [Math.floor(rand() * 61)];
  }
  const limit = 1e15;
  const roll = rand();
  if (roll < 0.1) return [limit - Math.floor(rand() * 4)];
  let num = Math.floor(rand() * 1e7) * 1e8 + Math.floor(rand() * 1e8);
  if (num > limit) num = limit;
  if (rand() < 0.5) num -= num % 3;
  return [num];
}
